1	// Room bookings page script. Classic script: runs its setup at once.
2	(function () {
3	  'use strict';
4	
5	  var NO_REPLY = 'Could not reach the server.';
6	  var FALLBACK = 'Request failed.';
7	
8	  var form = document.getElementById('booking-form');
9	  var roomSelect = document.getElementById('room');
10	  var titleInput = document.getElementById('title');
11	  var dateInput = document.getElementById('date');
12	  var startInput = document.getElementById('start');
13	  var endInput = document.getElementById('end');
14	  var bookButton = document.getElementById('book');
15	  var filterInput = document.getElementById('filter-date');
16	  var showAllButton = document.getElementById('show-all');
17	  var list = document.getElementById('booking-list');
18	  var errorBox = document.getElementById('error');
19	
20	  var listSeq = 0;
21	
22	  function showError(text) {
23	    errorBox.textContent = text;
24	  }
25	
26	  function errorMessage(body) {
27	    var isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
28	    return isObject && typeof body.error === 'string' ? body.error : FALLBACK;
29	  }
30	
31	  // Resolves to { reply: false } when there is no usable reply, otherwise
32	  // { reply: true, ok, body }. A 204 body is never read.
33	  function request(url, options, successStatus) {
34	    return fetch(url, options).then(function (res) {
35	      if (res.status === 204) {
36	        return { reply: true, ok: successStatus === 204, body: null };
37	      }
38	      return res.json().then(function (body) {
39	        return { reply: true, ok: res.status === successStatus, body: body };
40	      });
41	    }).then(null, function () {
42	      return { reply: false };
43	    });
44	  }
45	
46	  function outcomeError(outcome) {
47	    return outcome.reply ? errorMessage(outcome.body) : NO_REPLY;
48	  }
49	
50	  function loadRooms() {
51	    request('/api/rooms', { method: 'GET' }, 200).then(function (outcome) {
52	      if (!outcome.ok) {
53	        showError(outcomeError(outcome));
54	        return;
55	      }
56	      var rooms = outcome.body && Array.isArray(outcome.body.rooms) ? outcome.body.rooms : [];
57	      roomSelect.replaceChildren.apply(roomSelect, rooms.map(function (name) {
58	        var option = document.createElement('option');
59	        option.value = name;
60	        option.textContent = name;
61	        return option;
62	      }));
63	    });
64	  }
65	
66	  function bookingItem(booking) {
67	    var li = document.createElement('li');
68	    var cancel = document.createElement('button');
69	    cancel.type = 'button';
70	    cancel.textContent = 'Cancel';
71	    cancel.addEventListener('click', function () {
72	      cancelBooking(cancel, booking.id);
73	    });
74	    li.append(
75	      booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
76	        booking.room + ': ' + booking.title,
77	      cancel
78	    );
79	    return li;
80	  }
81	
82	  function renderBookings(bookings) {
83	    if (bookings.length === 0) {
84	      var empty = document.createElement('li');
85	      empty.append('No bookings.');
86	      list.replaceChildren(empty);
87	      return;
88	    }
89	    list.replaceChildren.apply(list, bookings.map(bookingItem));
90	  }
91	
92	  function loadList() {
93	    listSeq += 1;
94	    var seq = listSeq;
95	    var filter = filterInput.value;
96	    var url = filter === '' ? '/api/bookings' : '/api/bookings?date=' + filter;
97	    request(url, { method: 'GET' }, 200).then(function (outcome) {
98	      if (seq !== listSeq) {
99	        return;
100	      }
101	      if (!outcome.ok) {
102	        showError(outcomeError(outcome));
103	        return;
104	      }
105	      var bookings = outcome.body && Array.isArray(outcome.body.bookings) ? outcome.body.bookings : [];
106	      renderBookings(bookings);
107	    });
108	  }
109	
110	  function cancelBooking(button, id) {
111	    button.disabled = true;
112	    request('/api/bookings/' + id, { method: 'DELETE' }, 204).then(function (outcome) {
113	      button.disabled = false;
114	      if (!outcome.reply) {
115	        showError(NO_REPLY);
116	        return;
117	      }
118	      showError(outcome.ok ? '' : errorMessage(outcome.body));
119	      loadList();
120	    });
121	  }
122	
123	  function submitBooking(event) {
124	    event.preventDefault();
125	    if (bookButton.disabled) {
126	      return;
127	    }
128	    bookButton.disabled = true;
129	    var payload = {
130	      room: roomSelect.value,
131	      title: titleInput.value,
132	      date: dateInput.value,
133	      start: startInput.value,
134	      end: endInput.value
135	    };
136	    request('/api/bookings', {
137	      method: 'POST',
138	      headers: { 'Content-Type': 'application/json' },
139	      body: JSON.stringify(payload)
140	    }, 201).then(function (outcome) {
141	      bookButton.disabled = false;
142	      if (!outcome.ok) {
143	        showError(outcomeError(outcome));
144	        return;
145	      }
146	      titleInput.value = '';
147	      showError('');
148	      loadList();
149	    });
150	  }
151	
152	  form.addEventListener('submit', submitBooking);
153	  filterInput.addEventListener('change', loadList);
154	  showAllButton.addEventListener('click', function () {
155	    filterInput.value = '';
156	    loadList();
157	  });
158	
159	  loadRooms();
160	  loadList();
161	})();
