1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import vm from 'node:vm';
4	import { readFileSync } from 'node:fs';
5	import {
6	  createPage, respond, respondBadJson, fail, flush, dispatch, deferred, textOf,
7	} from './app-fake-dom.mjs';
8	
9	const html = readFileSync(new URL('../public/index.html', import.meta.url), 'utf8');
10	const appSrc = readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');
11	const NO_REPLY = 'Could not reach the server.';
12	const B1 = { id: 1, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00' };
13	const B2 = { id: 2, room: 'Cosmos', title: '<b>x</b>', date: '2026-11-03', start: '11:00', end: '12:00' };
14	
15	// ---------- Part 1: static checks ----------
16	
17	const formHtml = html.slice(html.indexOf('<form'), html.indexOf('</form>'));
18	const outside = html.replace(formHtml, '');
19	
20	function labelText(id) {
21	  const m = html.match(new RegExp('<label[^>]*\\bfor="' + id + '"[^>]*>([\\s\\S]*?)</label>'));
22	  return m ? m[1] : null;
23	}
24	
25	test('title and single h1', () => {
26	  assert.equal(html.match(/<title>([^<]*)<\/title>/)[1], 'Room bookings');
27	  const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/g)];
28	  assert.equal(h1s.length, 1);
29	  assert.equal(h1s[0][1], 'Room bookings');
30	});
31	
32	test('form has novalidate and its controls', () => {
33	  assert.match(html, /<form\b[^>]*\bid="booking-form"[^>]*\bnovalidate\b/);
34	  assert.match(formHtml, /<select\b(?=[^>]*\bid="room")(?=[^>]*\bname="room")[^>]*>/);
35	  assert.match(formHtml, /<input\b(?=[^>]*\btype="text")(?=[^>]*\bid="title")(?=[^>]*\bname="title")[^>]*>/);
36	  assert.match(formHtml, /<input\b(?=[^>]*\btype="date")(?=[^>]*\bid="date")(?=[^>]*\bname="date")[^>]*>/);
37	  assert.match(formHtml, /<input\b(?=[^>]*\btype="time")(?=[^>]*\bid="start")(?=[^>]*\bname="start")[^>]*>/);
38	  assert.match(formHtml, /<input\b(?=[^>]*\btype="time")(?=[^>]*\bid="end")(?=[^>]*\bname="end")[^>]*>/);
39	  assert.match(formHtml, /<button\b(?=[^>]*\btype="submit")(?=[^>]*\bid="book")[^>]*>Book<\/button>/);
40	});
41	
42	test('labels have exact text and do not wrap fields', () => {
43	  const expected = { room: 'Room', title: 'Title', date: 'Date', start: 'Start', end: 'End', 'filter-date': 'Show date' };
44	  for (const [id, text] of Object.entries(expected)) {
45	    const inner = labelText(id);
46	    assert.equal(inner, text, 'label for ' + id);
47	    assert.ok(!inner.includes('<'));
48	  }
49	});
50	
51	test('controls outside the form', () => {
52	  assert.match(outside, /<input\b(?=[^>]*\btype="date")(?=[^>]*\bid="filter-date")[^>]*>/);
53	  assert.match(outside, /<button\b(?=[^>]*\btype="button")(?=[^>]*\bid="show-all")[^>]*>Show all<\/button>/);
54	  assert.match(outside, /<ul\b[^>]*\bid="booking-list"[^>]*>/);
55	  assert.match(outside, /<p\b(?=[^>]*\bid="error")(?=[^>]*\brole="alert")[^>]*><\/p>/);
56	});
57	
58	test('script is the last element of body, single and plain', () => {
59	  const before = html.slice(0, html.indexOf('</body>')).trim();
60	  assert.ok(before.endsWith('<script src="/app.js"></script>'));
61	  assert.equal(html.match(/<script/g).length, 1);
62	  const tag = html.match(/<script[^>]*>/)[0];
63	  assert.doesNotMatch(tag, /\b(type|defer|async)\b/);
64	});
65	
66	test('no rooms, handlers or absolute URLs in the page', () => {
67	  assert.doesNotMatch(html, /<option/);
68	  assert.doesNotMatch(html, /Aurora|Borealis|Cosmos/);
69	  assert.doesNotMatch(html, / on[a-z]+=/i);
70	  for (const src of [html, appSrc]) {
71	    assert.ok(!src.includes('http' + '://'));
72	    assert.ok(!src.includes('https' + '://'));
73	  }
74	  assert.doesNotMatch(appSrc, /^\s*(import|export)\b/m);
75	});
76	
77	// ---------- Part 2: behaviour ----------
78	
79	function load() {
80	  const page = createPage(appSrc);
81	  page.run();
82	  return page;
83	}
84	
85	const listItems = (page) => page.els['booking-list'].children;
86	const errorText = (page) => textOf(page.els.error);
87	const listCalls = (page) => page.calls.filter((c) => c.url.startsWith('/api/bookings') && (!c.options || !c.options.method || c.options.method === 'GET'));
88	const isGet = (c) => !c.options || !c.options.method || c.options.method === 'GET';
89	
90	async function renderList(page, bookings) {
91	  respond(page.calls[1], 200, { bookings });
92	  await flush();
93	}
94	
95	function fillForm(page) {
96	  const v = { room: 'Aurora', title: '  Standup  ', date: '2026-11-03', start: '09:00', end: '10:00' };
97	  for (const [k, val] of Object.entries(v)) page.els[k].value = val;
98	  return v;
99	}
100	
101	test('1. load starts rooms and list fetches synchronously', () => {
102	  const page = load();
103	  assert.equal(page.calls.length, 2);
104	  assert.equal(page.calls[0].url, '/api/rooms');
105	  assert.equal(page.calls[1].url, '/api/bookings');
106	  assert.ok(page.calls.every(isGet));
107	});
108	
109	test('2. rooms fill the select', async () => {
110	  const page = load();
111	  respond(page.calls[0], 200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
112	  await flush();
113	  const opts = page.els.room.children;
114	  assert.equal(opts.length, 3);
115	  ['Aurora', 'Borealis', 'Cosmos'].forEach((n, i) => {
116	    assert.equal(opts[i].tag, 'option');
117	    assert.equal(opts[i].value, n);
118	    assert.equal(textOf(opts[i]), n);
119	  });
120	  assert.equal(errorText(page), '');
121	});
122	
123	test('3. rooms error statuses', async () => {
124	  const cases = [[{ error: 'internal error' }, 'internal error'], [{ error: 5 }, 'Request failed.'],
125	    [['x'], 'Request failed.'], [null, 'Request failed.']];
126	  for (const [body, expected] of cases) {
127	    const page = load();
128	    respond(page.calls[0], 500, body);
129	    await flush();
130	    assert.equal(errorText(page), expected);
131	    assert.equal(page.els.room.children.length, 0);
132	  }
133	});
134	
135	test('4. rooms without a reply', async () => {
136	  let page = load();
137	  fail(page.calls[0]);
138	  await flush();
139	  assert.equal(errorText(page), NO_REPLY);
140	  assert.equal(page.els.room.children.length, 0);
141	  page = load();
142	  respondBadJson(page.calls[0], 200);
143	  await flush();
144	  assert.equal(errorText(page), NO_REPLY);
145	});
146	
147	test('5. list rendering', async () => {
148	  const page = load();
149	  await renderList(page, [B1, B2]);
150	  const items = listItems(page);
151	  assert.equal(items.length, 2);
152	  for (const li of items) {
153	    assert.equal(li.tag, 'li');
154	    assert.equal(li.children.length, 2);
155	    assert.equal(li.children[1].tag, 'button');
156	    assert.equal(li.children[1].type, 'button');
157	    assert.equal(textOf(li.children[1]), 'Cancel');
158	    assert.ok(li.children[0].isText);
159	  }
160	  assert.equal(items[0].children[0].text, '2026-11-03 09:00-10:00 Aurora: Standup');
161	  assert.equal(items[1].children[0].text, '2026-11-03 11:00-12:00 Cosmos: <b>x</b>');
162	});
163	
164	test('6. empty list', async () => {
165	  const page = load();
166	  await renderList(page, []);
167	  const items = listItems(page);
168	  assert.equal(items.length, 1);
169	  assert.equal(items[0].tag, 'li');
170	  assert.equal(items[0].children.length, 1);
171	  assert.deepEqual(items[0].children[0], { isText: true, text: 'No bookings.' });
172	});
173	
174	test('7. list errors keep the list; success keeps the error', async () => {
175	  let page = load();
176	  await renderList(page, [B1]);
177	  const before = listItems(page);
178	  dispatch(page.els['filter-date'], 'change');
179	  respond(page.calls[2], 400, { error: 'date must be a valid YYYY-MM-DD date' });
180	  await flush();
181	  assert.equal(errorText(page), 'date must be a valid YYYY-MM-DD date');
182	  assert.equal(listItems(page), before);
183	  dispatch(page.els['filter-date'], 'change');
184	  fail(page.calls[3]);
185	  await flush();
186	  assert.equal(errorText(page), NO_REPLY);
187	  assert.equal(listItems(page), before);
188	
189	  page = load();
190	  fail(page.calls[0]);
191	  await flush();
192	  await renderList(page, [B1]);
193	  assert.equal(errorText(page), NO_REPLY);
194	  assert.equal(listItems(page).length, 1);
195	});
196	
197	test('8. filter change fetches, input does not', async () => {
198	  const page = load();
199	  page.els['filter-date'].value = '2026-11-03';
200	  dispatch(page.els['filter-date'], 'input');
201	  assert.equal(page.calls.length, 2);
202	  dispatch(page.els['filter-date'], 'change');
203	  assert.equal(page.calls.length, 3);
204	  assert.equal(page.calls[2].url, '/api/bookings?date=2026-11-03');
205	  page.els['filter-date'].value = 'a b&c';
206	  dispatch(page.els['filter-date'], 'change');
207	  assert.equal(page.calls[3].url, '/api/bookings?date=a b&c');
208	});
209	
210	test('9. overlapping list fetches: only the last one counts', async () => {
211	  let page = load();
212	  dispatch(page.els['filter-date'], 'change');
213	  respond(page.calls[2], 200, { bookings: [B1] });
214	  await flush();
215	  respond(page.calls[1], 200, { bookings: [B2, B2] });
216	  await flush();
217	  assert.equal(listItems(page).length, 1);
218	  assert.equal(listItems(page)[0].children[0].text, '2026-11-03 09:00-10:00 Aurora: Standup');
219	
220	  for (const stale of [(c) => fail(c), (c) => respond(c, 500, { error: 'boom' })]) {
221	    page = load();
222	    dispatch(page.els['filter-date'], 'change');
223	    respond(page.calls[2], 200, { bookings: [B1] });
224	    await flush();
225	    stale(page.calls[1]);
226	    await flush();
227	    assert.equal(errorText(page), '');
228	    assert.equal(listItems(page).length, 1);
229	  }
230	
231	  page = load();
232	  dispatch(page.els['filter-date'], 'change');
233	  respond(page.calls[1], 200, { bookings: [B2] });
234	  await flush();
235	  assert.equal(listItems(page).length, 0);
236	  assert.equal(errorText(page), '');
237	  respond(page.calls[2], 200, { bookings: [B1] });
238	  await flush();
239	  assert.equal(listItems(page).length, 1);
240	});
241	
242	test('10. show all clears the filter and fetches once', () => {
243	  const page = load();
244	  page.els['filter-date'].value = '2026-11-03';
245	  const n = page.calls.length;
246	  dispatch(page.els['show-all'], 'click');
247	  assert.equal(page.els['filter-date'].value, '');
248	  assert.equal(page.calls.length, n + 1);
249	  assert.equal(page.calls[n].url, '/api/bookings');
250	});
251	
252	test('11. submit happy path', async () => {
253	  const page = load();
254	  const v = fillForm(page);
255	  page.els.error.children = [{ isText: true, text: 'old' }];
256	  const ev = dispatch(page.els['booking-form'], 'submit');
257	  assert.ok(ev.prevented);
258	  assert.equal(page.els.book.disabled, true);
259	  assert.equal(page.calls.length, 3);
260	  const post = page.calls[2];
261	  assert.equal(post.url, '/api/bookings');
262	  assert.equal(post.options.method, 'POST');
263	  // The headers object comes from the vm realm, so compare a same-realm copy.
264	  assert.deepEqual({ ...post.options.headers }, { 'Content-Type': 'application/json' });
265	  assert.deepEqual(Object.keys(JSON.parse(post.options.body)).sort(), Object.keys(v).sort());
266	  assert.deepEqual(JSON.parse(post.options.body), v);
267	  assert.ok(dispatch(page.els['booking-form'], 'submit').prevented);
268	  assert.equal(page.calls.length, 3);
269	  respond(post, 201, B1);
270	  await flush();
271	  assert.equal(page.els.book.disabled, false);
272	  assert.equal(page.els.title.value, '');
273	  assert.equal(page.els.room.value, 'Aurora');
274	  assert.equal(page.els.date.value, '2026-11-03');
275	  assert.equal(page.els.start.value, '09:00');
276	  assert.equal(page.els.end.value, '10:00');
277	  assert.equal(errorText(page), '');
278	  assert.equal(page.calls.length, 4);
279	  assert.equal(page.calls[3].url, '/api/bookings');
280	  assert.ok(isGet(page.calls[3]));
281	});
282	
283	test('12. Book re-enabled only after the body has arrived', async () => {
284	  const page = load();
285	  fillForm(page);
286	  dispatch(page.els['booking-form'], 'submit');
287	  const gate = deferred();
288	  respond(page.calls[2], 201, B1, { gate: gate.promise });
289	  await flush();
290	  assert.equal(page.els.book.disabled, true);
291	  gate.resolve();
292	  await flush();
293	  assert.equal(page.els.book.disabled, false);
294	});
295	
296	test('13. submit failures keep form and skip refetch', async () => {
297	  const cases = [
298	    (c) => respond(c, 409, { error: 'room is already booked from 09:00 to 10:00' }),
299	    (c) => fail(c),
300	    (c) => respondBadJson(c, 201),
301	  ];
302	  const expected = ['room is already booked from 09:00 to 10:00', NO_REPLY, NO_REPLY];
303	  for (const [i, settle] of cases.entries()) {
304	    const page = load();
305	    fillForm(page);
306	    dispatch(page.els['booking-form'], 'submit');
307	    settle(page.calls[2]);
308	    await flush();
309	    assert.equal(errorText(page), expected[i]);
310	    assert.equal(page.els.book.disabled, false);
311	    assert.equal(page.els.title.value, '  Standup  ');
312	    assert.equal(page.calls.length, 3);
313	  }
314	});
315	
316	async function cancelSetup() {
317	  const page = load();
318	  await renderList(page, [{ ...B1, id: 7 }]);
319	  page.els.error.children = [{ isText: true, text: 'old' }];
320	  const button = listItems(page)[0].children[1];
321	  dispatch(button, 'click');
322	  return { page, button };
323	}
324	
325	test('14. cancel: 204 clears error and refetches without reading body', async () => {
326	  const { page, button } = await cancelSetup();
327	  assert.equal(button.disabled, true);
328	  const del = page.calls[2];
329	  assert.equal(del.url, '/api/bookings/7');
330	  assert.equal(del.options.method, 'DELETE');
331	  respond(del, 204, null);
332	  await flush();
333	  assert.equal(del.jsonCalled, false);
334	  assert.equal(button.disabled, false);
335	  assert.equal(errorText(page), '');
336	  assert.equal(page.calls.length, 4);
337	  assert.equal(page.calls[3].url, '/api/bookings');
338	});
339	
340	test('14b. cancel: error status shows message and refetches', async () => {
341	  const { page, button } = await cancelSetup();
342	  respond(page.calls[2], 404, { error: 'booking not found' });
343	  await flush();
344	  assert.equal(errorText(page), 'booking not found');
345	  assert.equal(button.disabled, false);
346	  assert.equal(page.calls.length, 4);
347	  assert.equal(page.calls[3].url, '/api/bookings');
348	});
349	
350	test('14c. cancel: no reply shows message and does not refetch', async () => {
351	  const settlers = [(c) => fail(c), (c) => respondBadJson(c, 404)];
352	  for (const settle of settlers) {
353	    const { page, button } = await cancelSetup();
354	    settle(page.calls[2]);
355	    await flush();
356	    assert.equal(errorText(page), NO_REPLY);
357	    assert.equal(button.disabled, false);
358	    assert.equal(page.calls.length, 3);
359	  }
360	});
361	
362	test('15. fakes enforce the API allowlist', () => {
363	  const page = load();
364	  assert.throws(() => vm.runInContext('document.body', page.ctx), /forbidden/);
365	  assert.throws(() => vm.runInContext("document.getElementById('room').innerHTML = 'x'", page.ctx), /forbidden/);
366	  assert.throws(() => vm.runInContext("document.getElementById('room').appendChild", page.ctx), /forbidden/);
