2	// Proxies that throw on any member outside the allowed list.
3	import vm from 'node:vm';
4	
5	const IDS = ['booking-form', 'room', 'title', 'date', 'start', 'end', 'book',
6	  'filter-date', 'show-all', 'booking-list', 'error'];
7	const EL_GET = ['textContent', 'value', 'type', 'disabled', 'append',
8	  'replaceChildren', 'addEventListener'];
9	const EL_SET = ['textContent', 'value', 'type', 'disabled'];
10	
11	function forbid(prop) {
12	  return new Error('forbidden: ' + String(prop));
13	}
14	
15	function allowOnly(target, getters, setters, label) {
16	  return new Proxy(target, {
17	    get(t, prop) {
18	      // Promise resolution probes `then`; a real object simply lacks it.
19	      if (typeof prop === 'symbol' || prop === 'then') return undefined;
20	      if (!getters.includes(prop)) throw forbid(label + '.' + prop);
21	      return t[prop];
22	    },
23	    set(t, prop, value) {
24	      if (!setters.includes(prop)) throw forbid(label + '.' + prop);
25	      t[prop] = value;
26	      return true;
27	    },
28	  });
29	}
30	
31	export function textOf(node) {
32	  return node.isText ? node.text : node.children.map(textOf).join('');
33	}
34	
35	function makeInternal(tag, id = '') {
36	  return { tag, id, children: [], listeners: {}, value: '', type: '', disabled: false };
37	}
38	
39	function toNode(arg, internals) {
40	  if (typeof arg === 'string') return { isText: true, text: arg };
41	  const node = internals.get(arg);
42	  if (!node) throw new Error('unknown node passed to append');
43	  return node;
44	}
45	
46	function wrapElement(internal, internals) {
47	  const api = {
48	    append: (...args) => { internal.children.push(...args.map((a) => toNode(a, internals))); },
49	    replaceChildren: (...args) => { internal.children = args.map((a) => toNode(a, internals)); },
50	    addEventListener: (type, fn) => { (internal.listeners[type] ??= []).push(fn); },
51	    get value() { return internal.value; },
52	    set value(v) { internal.value = v; },
53	    get type() { return internal.type; },
54	    set type(v) { internal.type = v; },
55	    get disabled() { return internal.disabled; },
56	    set disabled(v) { internal.disabled = v; },
57	    get textContent() { return textOf(internal); },
58	    set textContent(v) {
59	      internal.children = v === '' ? [] : [{ isText: true, text: String(v) }];
60	    },
61	  };
62	  const proxy = allowOnly(api, EL_GET, EL_SET, 'element');
63	  internals.set(proxy, internal);
64	  return proxy;
65	}
66	
67	function makeDocument(els, proxies, internals) {
68	  const api = {
69	    getElementById: (id) => proxies[id] ?? null,
70	    createElement: (tag) => wrapElement(makeInternal(tag), internals),
71	  };
72	  return allowOnly(api, ['getElementById', 'createElement'], [], 'document');
73	}
74	
75	function makeResponse(status, body, opts, tracker) {
76	  const api = {
77	    status,
78	    json() {
79	      tracker.jsonCalled = true;
80	      if (opts.badJson) return Promise.reject(new SyntaxError('bad json'));
81	      const value = structuredClone(body);
82	      return opts.gate ? opts.gate.then(() => value) : Promise.resolve(value);
83	    },
84	  };
85	  return allowOnly(api, ['status', 'json'], [], 'response');
86	}
