94	export function createPage(appSource) {
95	  const els = {};
96	  const proxies = {};
97	  const internals = new WeakMap();
98	  for (const id of IDS) {
99	    els[id] = makeInternal(id === 'booking-list' ? 'ul' : id, id);
100	    proxies[id] = wrapElement(els[id], internals);
101	  }
102	  const calls = [];
103	  const fetch = (url, options) => {
104	    const d = deferred();
105	    calls.push({ url, options, d, jsonCalled: false });
106	    return d.promise;
107	  };
108	  const document = makeDocument(els, proxies, internals);
109	  const ctx = vm.createContext({ document, fetch });
110	  const page = { els, calls, ctx, internals };
111	  page.run = () => vm.runInContext(appSource, ctx);
112	  return page;
113	}
