131	export function dispatch(el, type) {
132	  const record = { prevented: false };
133	  const event = allowOnly({ preventDefault: () => { record.prevented = true; } },
134	    ['preventDefault'], [], 'event');
135	  for (const fn of el.listeners[type] ?? []) fn(event);
136	  return record;
